      target="_blank"
      rel="noreferrer"
      title="Escríbenos por WhatsApp"
      className="wa-btn fixed bottom-6 right-6 z-40 bg-green-500 hover:bg-green-600 text-white w-14 h-14 rounded-full shadow-xl shadow-green-500/40 flex items-center justify-center text-2xl transition-colors"
    >
      💬
    </a>
  );
}
